/**
 * Settings match the ten decision rows word for word (src/lib/decisions.ts appends hand-written questions to the
 * section whose setting matches), plus "Newly diagnosed", the appointment types and carers.
 */
export const pancreaticQuestions: Question[] = [
  // Newly diagnosed
  { setting: "Newly diagnosed", question: "Who is my clinical nurse specialist (my key worker), and what is the 24-hour number for the team?", why: "The NHS says your team will include a clinical nurse specialist who is your main point of contact during and after treatment; Pancreatic Cancer UK says if you have not been given a key contact, ask the doctor who to contact with questions." },
  { setting: "Newly diagnosed", question: "Can the cancer be removed, and which word describes mine: resectable, borderline resectable, locally advanced or metastatic?", why: "Cancer Research UK says the team first looks at your scans to see if they can remove the cancer, and that word decides whether treatment starts with an operation, with chemotherapy, or with treatment to control the cancer." },
  { setting: "Newly diagnosed", question: "Has my case been discussed at the specialist pancreatic cancer multidisciplinary team meeting, and when will I hear what was decided?", why: "NICE NG85 says a specialist pancreatic cancer multidisciplinary team should make a shared decision with the person about the care that is needed; Cancer Research UK lists who sits on it, including a dietitian and a palliative care doctor." },
  { setting: "Newly diagnosed", question: "Do I need a biopsy before treatment, and have I had a pancreas-protocol CT of the chest, abdomen and pelvis?", why: "Pancreatic Cancer UK says you will need a biopsy to confirm the diagnosis before some treatments, including chemotherapy or clinical trials; NICE NG85 says everyone newly diagnosed should be offered a pancreatic protocol CT scan including the chest, abdomen and pelvis." },
  { setting: "Newly diagnosed", question: "Should I be taking pancreatic enzymes now, and can I be referred to a dietitian this week?", why: "Pancreatic Cancer UK says most people with pancreatic cancer will need to take PERT and to ask if you have digestion symptoms and have not been prescribed it; NICE NG85 says offer enteric-coated pancreatin for unresectable disease and consider it before and after resection." },
  { setting: "Newly diagnosed", question: "Will I be offered germline (inherited) genetic testing, and does it change my treatment or matter for my relatives?", why: "NICE NG85 asks teams to ask about first-degree relatives with pancreatic cancer; the OnCo record lists a germline panel among the tests; a BRCA result can open olaparib and starts a conversation about relatives." },
  { setting: "Newly diagnosed", question: "Can I get a second opinion from a specialist pancreatic centre without delaying treatment?", why: "Cancer Research UK says you can ask your specialist or GP to refer you to a doctor or surgeon specialising in pancreatic cancer, and that arranging it through your specialist means your notes and results go with you; Pancreatic Cancer UK adds that different teams can disagree about whether surgery is possible." },
  // Surgery first or chemotherapy first
  { setting: S_ORDER, question: "Is my cancer resectable or borderline resectable, and what on the scan makes the difference?", why: "Cancer Research UK explains that borderline resectable means the cancer may be involving a main blood vessel, so it is less clear if surgery is possible; the OnCo subtype records describe the vessel contact that defines each class." },
  { setting: S_ORDER, question: "If it is resectable, why are you recommending surgery first (or chemotherapy first), and what does NICE say?", why: "NICE NG85 says only consider neoadjuvant therapy for people with resectable or borderline resectable pancreatic cancer as part of a clinical trial; Pancreatic Cancer UK says surgery is the best treatment for cancer that has not spread outside the pancreas." },
  { setting: S_ORDER, question: "If it is borderline, how many months of chemotherapy would I have before restaging, and what would make surgery possible or not?", why: "Cancer Research UK says you might have chemotherapy first to shrink the cancer, then a scan to help the surgeon decide; Pancreatic Cancer UK says the operation usually happens around 6 to 8 weeks after chemotherapy finishes and that a vein resection may be needed." },
  { setting: S_ORDER, question: "How many of these operations does this unit do each year, and what are its complication rates?", why: "Macmillan says only a specialist surgeon with experience in pancreatic cancer surgery does this operation and you may be referred to a specialist centre for it." },
  { setting: S_ORDER, question: "What can I do before surgery to recover faster, and is there a prehabilitation programme?", why: "Pancreatic Cancer UK says some hospitals offer prehabilitation focused on diet and physical activity, which can help you recover more quickly after surgery; Macmillan says stopping smoking before the operation lowers the risk of a chest infection." },
  { setting: S_ORDER, question: "What happens if the surgeon finds during the operation that the cancer cannot be removed?", why: "Pancreatic Cancer UK says the surgeon may switch to bypass surgery, which does not treat the cancer but can help symptoms; NICE NG85 says consider surgical biliary bypass and prophylactic gastrojejunostomy if the cancer is found to be unresectable during attempted resection." },
  // Which chemotherapy
  { setting: S_WHICH_CHEMO, question: "Which chemotherapy do you recommend for me, and what about my fitness, my liver tests or my nerves made you choose it?", why: "NICE NG85 offers FOLFIRINOX to people with metastatic disease and a performance status of 0 to 1, gemcitabine combination therapy to those not well enough for FOLFIRINOX, and gemcitabine alone to those not well enough for combination chemotherapy." },
  { setting: S_WHICH_CHEMO, question: "Is NALIRIFOX an option for me, and is it funded where I am treated?", why: "In NAPOLI 3, NALIRIFOX improved survival over gemcitabine with nab-paclitaxel; the OnCo record lists it beside modified FOLFIRINOX for fit patients, but NHS funding follows NICE appraisals, so ask what applies locally." },
  { setting: S_WHICH_CHEMO, question: "Will I have a DPD blood test before fluorouracil or capecitabine?", why: "Macmillan and Cancer Research UK say you should have a blood test for DPD deficiency before these drugs, because low DPD raises the risk of severe or life-threatening side effects and the dose may be lowered." },
  { setting: S_WHICH_CHEMO, question: "Which side effects are most likely with my regimen, and what are the exact rules for ringing the 24-hour line?", why: "Macmillan's FOLFIRINOX page says to ring straight away for a temperature above 37.5 C or below 36 C, for diarrhoea 4 or more times a day or at night, or if anti-diarrhoea medicine has not worked within 24 hours; its nab-paclitaxel page uses 3 or more loose stools a day." },
  { setting: S_WHICH_CHEMO, question: "How will we know the treatment is working, and what is the plan if it stops?", why: "Pancreatic Cancer UK says you will have a scan every three months to see how the chemotherapy is working; NICE NG85 describes second-line options depending on what was given first." },
  { setting: S_WHICH_CHEMO, question: "Will I need a PICC line or port, and will I carry a pump home?", why: "Macmillan says FOLFIRINOX is given every 2 weeks with the fluorouracil running through a small pump for about 46 hours, and that you may have a PICC line put in for it." },
  // Adjuvant after Whipple
  { setting: S_ADJUVANT, question: "Which chemotherapy after surgery do you recommend, for how long, and why that one for me?", why: "Pancreatic Cancer UK lists FOLFIRINOX, gemcitabine with capecitabine (GemCap) and gemcitabine alone after surgery, chosen by how well you are; in PRODIGE 24 modified FOLFIRINOX gave a median survival of 54.4 months against 35.0 with gemcitabine." },
  { setting: S_ADJUVANT, question: "When does the chemotherapy need to start, and what if I have not recovered enough by then?", why: "Cancer Research UK and Pancreatic Cancer UK say adjuvant chemotherapy should start within 12 weeks (3 months) of surgery and lasts up to 6 months; NICE NG85 says start once the person has recovered and as soon as they are well enough to tolerate all 6 cycles." },
  { setting: S_ADJUVANT, question: "Can eating, weight and my enzyme dose be sorted out first so they do not delay the chemotherapy?", why: "Pancreatic Cancer UK says to speak to your doctor, nurse or dietitian about digestion problems after surgery so they do not delay chemotherapy." },
  { setting: S_ADJUVANT, question: "What did the pathology show about the margins and lymph nodes, and does it change what you advise?", why: "The OnCo record for resectable disease lists margin status (R0 versus R1) and lymph node ratio among the results that carry prognosis; ask what yours were." },
  { setting: S_ADJUVANT, question: "What will follow-up look like after chemotherapy, and which symptoms should prompt an early call?", why: "Cancer Research UK says after surgery you usually have CT scans every 6 months for 5 years, with blood tests and sometimes tumour markers at each visit; NICE NG85 asks for ongoing specialist assessment for problems resulting from surgery." },
  // Germline testing
  { setting: S_GERMLINE, question: "Which genes will be tested, on blood or on the tumour, and how long will the result take?", why: "The NHS says a hospital specialist can arrange genomic testing on a sample already taken; the OnCo record lists BRCA1, BRCA2, PALB2, ATM, CDKN2A, STK11 and Lynch genes on the germline panel." },
  { setting: S_GERMLINE, question: "If I carry a BRCA variant, does olaparib apply to me, and is it funded on the NHS?", why: "In POLO, maintenance olaparib after at least 16 weeks of platinum chemotherapy lengthened the time before the cancer grew in germline BRCA carriers; NICE could not make a recommendation (TA750, terminated) because the company made no submission, so ask what is funded where you are treated." },
  { setting: S_GERMLINE, question: "Does a BRCA or PALB2 result change which chemotherapy you would give me?", why: "The OnCo subtype records note platinum-based chemotherapy is favoured where there is a BRCA or PALB2 variant; Macmillan says olaparib might be used after chemotherapy in BRCA-mutated pancreatic cancer." },
  { setting: S_GERMLINE, question: "If a variant is found, which relatives could be tested, and could they be offered monitoring?", why: "Pancreatic Cancer UK says NICE recommends monitoring for people with a BRCA1, BRCA2, PALB2 or CDKN2A variant and a first-degree relative with pancreatic cancer; NICE NG85 lists the surveillance criteria and the MRI/MRCP or EUS used." },
  { setting: S_GERMLINE, question: "What does a variant of uncertain significance mean for me and my family?", why: "The NHS says a test can reveal information about relatives that you or they did not know and that a genetic counsellor can talk this through; Pancreatic Cancer UK explains that having a gene variant does not always mean someone will develop cancer." },
  // Jaundice
  { setting: S_JAUNDICE, question: "Does my jaundice need to be relieved before treatment, and how: a stent, or straight to surgery?", why: "NICE NG85 says offer resectional surgery rather than preoperative biliary drainage to people with resectable cancer and jaundice who are well enough and not in a trial requiring drainage; Pancreatic Cancer UK says if you are not fit enough yet, or will have chemotherapy first, you may need a stent." },
  { setting: S_JAUNDICE, question: "Will the stent be plastic or metal, and will it need changing later?", why: "NICE NG85 says offer self-expanding metal stents placed by endoscopy for unresectable disease and for resectable disease when the person is not yet fit for surgery; Macmillan says plastic stents may need replacing and metal ones usually do not." },
  { setting: S_JAUNDICE, question: "How long will the jaundice take to clear, and when can chemotherapy start?", why: "Pancreatic Cancer UK says it may take around two to three weeks for jaundice to go completely, that most people improve quite quickly, and that treating the jaundice may mean you can start or continue treatment for the cancer." },
  { setting: S_JAUNDICE, question: "What are the signs of a blocked or infected stent, and exactly who do I ring, day or night?", why: "Pancreatic Cancer UK says stents can get blocked, move or cause infection or pancreatitis; the NHS says ask for an urgent GP appointment or use 111 if the whites of the eyes or skin turn yellow, and call 999 for the signs of sepsis." },
  { setting: S_JAUNDICE, question: "Would a surgical bypass be better than a stent for me, and when is it done?", why: "NICE NG85 says offer metal stents rather than surgical bypass for unresectable disease and consider a bypass during an attempted resection if the cancer turns out to be unresectable; Pancreatic Cancer UK says bypass avoids the problem of stents blocking but is a big operation." },
  // Pain
  { setting: S_PAIN, question: "What is causing my pain, and which painkillers and other medicines will we try first?", why: "Pancreatic Cancer UK says the cancer can press on a bundle of nerves called the coeliac plexus, causing pain in the tummy or back; Cancer Research UK lists paracetamol, weak and strong opioids, anti-inflammatories, and amitriptyline or gabapentin for nerve pain." },
  { setting: S_PAIN, question: "Am I a candidate for a coeliac plexus block, and how would it be done?", why: "NICE NG85 says consider EUS-guided or image-guided percutaneous neurolytic coeliac plexus block for people with uncontrolled pancreatic pain, unacceptable opioid side effects or escalating doses of analgesics; Macmillan describes the injection through the back or via an endoscope." },
  { setting: S_PAIN, question: "Could radiotherapy or the chemotherapy itself help my pain?", why: "Cancer Research UK says palliative radiotherapy can help control pain or bleeding into the duodenum, and that cancer treatments can ease pain by shrinking the cancer, though it can take several weeks." },
  { setting: S_PAIN, question: "What should I take for constipation and sickness from opioids, and what if the pain is not controlled between visits?", why: "Cancer Research UK says most opioids cause constipation so regular laxatives are given, and that sickness usually settles in a few days; Pancreatic Cancer UK says to ask for help early because early treatment makes pain easier to deal with." },
  { setting: S_PAIN, question: "Can the palliative care or pain team be involved now, alongside my treatment?", why: "Macmillan says palliative care teams are experts in controlling pain, tiredness, bowel changes and appetite loss and are based in hospitals, hospices, palliative care units and pain clinics; the NHS says the team works alongside your treatment." },
  // Enzymes and diabetes
  { setting: S_ENZYMES, question: "How much PERT should I start with, and how do I know if I am taking enough?", why: "Pancreatic Cancer UK says you might start with at least 50,000 or 75,000 units for a main meal and 25,000 or 50,000 for a snack, take half with the first mouthfuls and the rest through the meal, take more with larger or fattier meals, and keep a food diary; the UK consensus guideline (Phillips 2021) sets the same starting doses." },
  { setting: S_ENZYMES, question: "Who reviews my enzyme dose, and what if my symptoms do not improve?", why: "Pancreatic Cancer UK says most people need to increase from the starting dose and the dietitian, doctor or nurse should review it regularly; if symptoms persist a proton pump inhibitor, a different brand, or another cause such as bile acid diarrhoea or small intestinal bacterial overgrowth may be looked for." },
  { setting: S_ENZYMES, question: "What should I do if I cannot get my usual brand of PERT?", why: "NICE NG85 notes the 2024 supply disruption and points prescribers to the Specialist Pharmacy Service tool for equivalent products; Pancreatic Cancer UK says to contact your dietitian, hospital team or GP and has guidance on managing when short." },
  { setting: S_ENZYMES, question: "Do I have, or am I likely to get, type 3c diabetes, and who will look after it?", why: "Pancreatic Cancer UK says pancreatic cancer or surgery can cause type 3c diabetes, which differs from type 1 and 2, and that a diabetes specialist nurse and a specialist dietitian should be involved; a meta-analysis found about 16 in 100 people develop new diabetes after a Whipple operation." },
  { setting: S_ENZYMES, question: "If I need insulin, what do I do about low blood sugar, driving and the DVLA?", why: "Cancer Research UK says you will be taught what to do if your blood sugar drops too low; Pancreatic Cancer UK says if you take insulin you must tell the DVLA (or DVA in Northern Ireland) and cannot drive until they say you can." },
  // Feeding and weight
  { setting: S_FEEDING, question: "Am I losing weight or muscle, and can I see a dietitian now rather than later?", why: "Cancer Research UK says most hospital pancreatic cancer teams include a dietitian; the ASCO cachexia guideline recommends dietary counselling and says no drug is established for cancer cachexia, so early nutrition support is the mainstay." },
  { setting: S_FEEDING, question: "Should I be taking nutritional supplement drinks, and do I need enzymes with them?", why: "Cancer Research UK says supplements are available on prescription and can boost calories and protein; Pancreatic Cancer UK says to take PERT with nutritional supplements as well as with meals, snacks and milky drinks." },
  { setting: S_FEEDING, question: "Do I need a special diet, and should I cut down on fat?", why: "Pancreatic Cancer UK says you do not need a special diet, there are no foods to avoid, and you should not reduce fat to manage symptoms but take more PERT instead; NICE NG85 says do not offer fish oils to manage weight loss in unresectable disease." },
  { setting: S_FEEDING, question: "If I cannot eat enough after surgery, will I be fed through a tube, and for how long?", why: "NICE NG85 says for people who have had a pancreatoduodenectomy and have a functioning gut, offer early enteral nutrition including oral and tube feeding rather than feeding into a vein; Pancreatic Cancer UK says a nasojejunal tube may be used if the stomach does not empty normally at first." },
  { setting: S_FEEDING, question: "What should I eat if I have a duodenal stent, and how do I keep it from blocking?", why: "Cancer Research UK says eat moist, soft, lower-fibre foods, little and often, chew thoroughly, add sauces and stay upright after eating; Pancreatic Cancer UK says you should be given diet information after the stent goes in." },
  // Trial or standard
  { setting: S_TRIAL, question: "Is there a trial I could join now, what is the comparison arm, and is a placebo involved?", why: "The NHS says a placebo is used only where no proven standard treatment exists; Pancreatic Cancer UK says most pancreatic cancer trials are looking at treatment options and has a trial finder." },
  { setting: S_TRIAL, question: "Do I need a biopsy or a tumour gene test to be eligible, and has tissue already been taken?", why: "Pancreatic Cancer UK says a biopsy is needed to confirm the diagnosis before chemotherapy or clinical trials; the OnCo record lists KRAS subtype, germline panel and fusion testing among the results that decide trial eligibility." },
  { setting: S_TRIAL, question: "Are KRAS inhibitor trials open to me, and where?", why: "Pancreatic Cancer UK describes KRAS inhibitors such as daraxonrasib as a promising group of treatments; the OnCo record lists RAS inhibitor trials in first and second line." },
  { setting: S_TRIAL, question: "What extra visits, tests and travel would the trial involve, and if I join and want to stop, what happens to my standard treatment?", why: "These are among the questions the NHS clinical trials page suggests asking; the NHS says you can leave a trial at any point without giving a reason and without it affecting your care." },
  // Palliative care early
  { setting: S_PALLIATIVE, question: "Can the palliative care or symptom control team see me now, while I am having treatment?", why: "Pancreatic Cancer UK says palliative care services are not just for the end of life and are available at any point for cancer that cannot be cured; a randomised trial found early palliative care improved quality of life and mood alongside cancer treatment." },
  { setting: S_PALLIATIVE, question: "Who looks after my symptoms between hospital visits, and who do we ring at night or at the weekend?", why: "Macmillan says palliative care teams work with you, your GP and other professionals and many have home care services; the NHS says the clinical nurse specialist or palliative care team can help you and your loved ones get support." },
  { setting: S_PALLIATIVE, question: "Can we talk about what matters most to me, and record my wishes for care if I become more unwell?", why: "Pancreatic Cancer UK says the palliative care team can support you with making decisions about your future care and can also support your family; its end of life pages describe making plans about future care." },
  { setting: S_PALLIATIVE, question: "If I decide not to have chemotherapy, or cannot have it, what care will I still get?", why: "Pancreatic Cancer UK says some people are not well enough for treatment or decide not to have it, and that you can still have treatments to help with symptoms from your GP, community or district nurses and the palliative care team." },
  // Appointment types
  { setting: "Surgeon appointment", question: "Can the cancer be removed completely, which operation would that be, and what would be removed?", why: "Macmillan describes the Whipple's and modified (pylorus-preserving) Whipple's procedures for cancers in the head of the pancreas, distal pancreatectomy for the body and tail, and the rare total pancreatectomy." },
  { setting: "Surgeon appointment", question: "Would I need chemotherapy before the operation, and how long after it would surgery be?", why: "Pancreatic Cancer UK says if the cancer is close to major blood vessels you may be offered chemotherapy first, with the operation usually around 6 to 8 weeks after it finishes." },
  { setting: "Surgeon appointment", question: "What will recovery look like: intensive care, hospital stay, eating, driving, work?", why: "Pancreatic Cancer UK says the first 24 to 48 hours are in intensive care or high dependency, hospital is usually one to two weeks, full recovery takes several months to a year, driving waits a few weeks and work may take at least three months." },
  { setting: "Surgeon appointment", question: "Will I need enzyme capsules, insulin or vaccinations after the operation?", why: "Macmillan says PERT is usually lifelong after surgery, that removing part or all of the pancreas can cause diabetes, and that if the spleen is removed you need lifelong vaccinations and possibly antibiotics." },
  { setting: "Surgeon appointment", question: "If the cancer cannot be removed once you start, would you do a bypass, and would you talk to me about that beforehand?", why: "Pancreatic Cancer UK says if this might happen your surgeon will discuss it before your operation; NICE NG85 says consider biliary bypass and prophylactic gastrojejunostomy in that situation." },
  { setting: "Oncologist appointment", question: "What is the aim of the treatment you are proposing, cure or control, and for how long would I have it?", why: "Macmillan's questions page says your team should explain the aim, benefits, disadvantages and alternatives of any treatment." },
  { setting: "Oncologist appointment", question: "Which regimen, how often, and which side effects are most likely for me? Which are reversible?", why: "Macmillan describes the schedules for FOLFIRINOX, GemCap and gemcitabine with nab-paclitaxel; Pancreatic Cancer UK says neuropathy is most common with FOLFIRINOX, FOLFOX or nab-paclitaxel and can get worse in the first months after treatment." },
  { setting: "Oncologist appointment", question: "Do I need a blood-thinning injection or tablet during chemotherapy to prevent a clot?", why: "Pancreatic Cancer UK says your oncologist should consider whether you need blood thinning medicine during chemotherapy; NICE NG85 points to its venous thromboembolism guideline for people with pancreatic cancer." },
  { setting: "Oncologist appointment", question: "How will we know if the treatment is working, and what would we do next if it stops working?", why: "Pancreatic Cancer UK says scans every three months; NICE NG85 describes oxaliplatin-based or gemcitabine-based second-line chemotherapy depending on what was given first." },
  { setting: "Dietitian appointment", question: "How much PERT should I take with meals, snacks and drinks, and how do I adjust it?", why: "Pancreatic Cancer UK gives the starting doses, the half-now-half-later rule, cool drinks only, more for fatty food, and a diet diary to find the right dose." },
  { setting: "Dietitian appointment", question: "How much weight have I lost, what is my target, and which supplements suit me?", why: "Cancer Research UK says nutritional supplements are available on prescription and that some may affect blood sugar if you have diabetes, so ask which is right for you." },
  { setting: "Dietitian appointment", question: "Which of my symptoms are digestion, which are the treatment, and which need another test?", why: "Pancreatic Cancer UK says if enzymes are not helping there may be another cause such as bile acid diarrhoea or small intestinal bacterial overgrowth, with tests and treatments for each." },
  { setting: "Dietitian appointment", question: "Should I change what I eat for diabetes, a duodenal stent or after surgery?", why: "Pancreatic Cancer UK says there is no special diet for pancreatic cancer; Cancer Research UK gives the soft, low-fibre advice after a duodenal stent and says a dietitian follows you closely with diabetes." },
  { setting: "Genomics appointment", question: "Which genes are being tested, what are the possible results, and how will I get them?", why: "The NHS explains referral and consent for genomic testing; Pancreatic Cancer UK explains inherited and acquired variants in plain words." },
  { setting: "Genomics appointment", question: "Is any result actionable now, on the NHS or in a trial?", why: "The OnCo record lists olaparib for germline BRCA, zenocutuzumab for NRG1 fusions, pembrolizumab for mismatch repair deficiency and NTRK inhibitors; NICE TA750 was terminated, so ask what is funded." },
  { setting: "Genomics appointment", question: "Which of my relatives could be offered testing or monitoring, and is there a letter I can give them?", why: "NICE NG85 lists who should be offered or considered for surveillance; Pancreatic Cancer UK says you can speak to your GP about a referral to a genetics centre." },
  { setting: "Palliative and supportive care appointment", question: "What can be done about my pain, sickness, itch, tiredness and appetite, and who adjusts the medicines between visits?", why: "Macmillan lists these among the symptoms palliative care teams are experts in; Cancer Research UK says many teams have home care services." },
  { setting: "Palliative and supportive care appointment", question: "What should my family watch for, and exactly who do we ring at night or at the weekend?", why: "The NHS gives the sepsis and jaundice wording; Pancreatic Cancer UK says a blood clot needs treating straight away and to go to A&E or call 999 if you cannot reach the team." },
  { setting: "Palliative and supportive care appointment", question: "What help is available at home, from a hospice, or for money and work, and how do we ask for a carer's assessment?", why: "Pancreatic Cancer UK says an SR1 form can speed up benefit claims where cancer cannot be cured, and lists PIP, Attendance Allowance and Carer's Allowance; the NHS says any carer over 18 can ask the council for a free carer's assessment." },
  { setting: "Palliative and supportive care appointment", question: "Can we talk about what matters most to me and record my wishes for care if I become more unwell?", why: "Marie Curie says palliative care can start at any stage and includes planning ahead; Pancreatic Cancer UK has pages on talking about dying and making plans for future care." },
  // Carers
  { setting: "For carers", question: "How can I be included in appointments and plans, and can I have copies of the treatment plan, the enzyme dose and the medicine list?", why: "Macmillan says to tell the healthcare team you are a carer so you can be part of the plans for going home; Pancreatic Cancer UK says learning about symptoms and who to ask for help is one of the best ways to help." },
  { setting: "For carers", question: "What are the signs of a blocked or infected stent, sepsis, a blood clot or a blocked bowel, and what should I do for each?", why: "The NHS, Pancreatic Cancer UK and Macmillan give the wording: fever or shivering, yellowing, vomiting large amounts, a swollen painful leg or sudden breathlessness, breathing fast, confusion, blotchy skin; the site's red cards quote them." },
  { setting: "For carers", question: "What support is there for me: a carer's assessment, Carer's Allowance, a break, or someone to talk to?", why: "The NHS says a carer's assessment is free for anyone over 18; Pancreatic Cancer UK has a booklet for carers and its nurses take calls from family members; Macmillan's line is open to carers." },
];

// ---------------------------------------------------------------- living with it: notes and links attached to records other files own
/**
 * Supplements (Spike.supplements, applied by applySpikeSupplements): each attaches `pancreatic` to a side-effect,
 * procedure or supportive-care record and adds short, sourced living-with notes and the patient page they were read
 * from. The records themselves belong to the files that define them; arrays append, nothing here overrides a scalar.
 */
const supplements: SpikeSupplement[] = [
  { id: "cachexia", cancers: [CANCER], links: [PCUK_DIET, CRUK_SYMPTOMS_ADVANCED, ROELAND_2020, ESPEN_2021],
    notes: [
      "Pancreatic cancer: weight loss has two causes that need separating, undigested food (too few pancreatic enzymes) and the cancer's own effect on appetite and muscle. Pancreatic Cancer UK says PERT can make a big difference and that you do not need a special diet; Cancer Research UK says eat little and often, choose high-calorie and high-protein foods, and ask the dietitian about prescribed supplement drinks.",
      "The ASCO cachexia guideline (Roeland 2020) recommends dietary counselling and says no drug is established for cancer cachexia; NICE NG85 says do not offer fish oils to manage weight loss in unresectable pancreatic cancer.",
    ] },
  { id: "obstructive-jaundice", cancers: [CANCER], links: [PCUK_JAUNDICE, NHS_JAUNDICE, NG85],
    notes: ["Pancreatic cancer in the head of the gland blocks the bile duct early, so jaundice is often the first sign. Pancreatic Cancer UK says surgery treats the jaundice if it is happening straight away, a stent is used if you are not yet fit or will have chemotherapy first, and it may take two to three weeks for the yellowing, itch and tiredness to clear. NICE NG85 says offer a pancreatic protocol CT before draining the bile duct."] },
  { id: "jaundice-and-itch-biliary", cancers: [CANCER], links: [PCUK_JAUNDICE, MAC_SYMPTOMS],
    notes: ["The same applies with pancreatic cancer: Macmillan says frequent lukewarm showers, avoiding drying soaps and moisturising lotions relieve the itch while you wait for a stent, and that treating the cause of the jaundice relieves the itching."] },
  { id: "stent-or-bypass-for-jaundice", cancers: [CANCER], links: [NG85, PCUK_BYPASS, PCUK_STENT_BILE],
    notes: ["Pancreatic cancer: NICE NG85 says offer endoscopically placed self-expanding metal stents rather than surgical bypass for unresectable disease, and consider a surgical bypass only if the cancer turns out to be unresectable during an attempted resection. Pancreatic Cancer UK says bypass avoids blocked stents and lasts longer but is a big operation with several days in hospital and a few months to recover."] },
  { id: "biliary-stent-problems", cancers: [CANCER], links: [PCUK_STENT_BILE, MAC_SYMPTOMS],
    notes: ["Pancreatic cancer: Pancreatic Cancer UK lists the problems as blockage (the old symptoms return), infection (treated with antibiotics), the stent moving (replaced) and pancreatitis from the procedure; Macmillan says plastic stents may need replacing after a long time and metal stents usually do not."] },
  { id: "acute-cholangitis", cancers: [CANCER], links: [NHS_SEPSIS, PCUK_STENT_BILE, PCUK_SURGERY_SIDE],
    notes: ["Pancreatic cancer with a stent or jaundice: fever or shivering is a same-day call to the 24-hour line, and the NHS says call 999 or go to A&E for breathing very fast, confusion or slurred speech, blue, pale or blotchy skin, a very high or very low temperature, or a rash that does not fade when pressed. Pancreatic Cancer UK says after surgery, sudden worse pain with a high temperature means going to A&E and telling them about your operation."] },
  { id: "duodenal-stenting-gastric-outlet", cancers: [CANCER], links: [PCUK_STENT_DUODENUM, PCUK_BYPASS, PCUK_SICK, CRUK_DIET, NG85],
    notes: ["Pancreatic cancer: vomiting large amounts, especially after food, and feeling full can mean the cancer is blocking the duodenum. Pancreatic Cancer UK says a duodenal stent takes 30 to 40 minutes under sedation and you should feel better within a couple of days; NICE NG85 says consider a gastrojejunostomy rather than a stent for people with a more favourable prognosis. Cancer Research UK's diet after a stent: soft, moist, lower-fibre food, little and often, chew well and stay upright."] },
  { id: "biliary-stenting-drainage", cancers: [CANCER], links: [PCUK_STENT_BILE, NG85], terms: ["stent-or-bypass-for-jaundice", "biliary-stent-problems", "acute-cholangitis"] },
  { id: "whipple", cancers: [CANCER], links: [PCUK_AFTER_SURGERY, PCUK_SURGERY_SIDE, PCUK_GOING_HOME, MAC_SURGERY, WENTE_2007],
    notes: [
      "Living with it: Pancreatic Cancer UK says the first 24 to 48 hours are in intensive care or high dependency, hospital is usually one to two weeks, and full recovery takes several months to a year. The stomach may not empty normally for the first days (the ISGPS calls this delayed gastric emptying) and some people are fed through a tube until it does; eating starts with drinks and soft food, in smaller portions.",
      "Longer term: most people need pancreatic enzyme capsules with food, some develop diabetes, blood-thinning injections continue for about four weeks at home, driving waits a few weeks and work often takes at least three months. Report a hot, painful, leaking wound, sudden worse pain or a high temperature straight away.",
    ] },
  { id: "resectability", cancers: [CANCER], links: [CRUK_DECISIONS, PCUK_WHO_SURGERY, NG85],
    notes: ["Pancreatic cancer: Cancer Research UK explains the three words in plain English (resectable: the surgeon can remove it; borderline resectable: it may involve a main blood vessel, so chemotherapy first is common; unresectable: locally advanced or metastatic). Pancreatic Cancer UK says different teams can read the scan differently and you can ask for a second opinion; NICE NG85 says neoadjuvant treatment for resectable or borderline disease should be within a clinical trial."] },
  { id: "peripheral-neuropathy", cancers: [CANCER], links: [PCUK_CHEMO_SIDE, MAC_FOLFIRINOX, NHS_NEUROPATHY, LOPRINZI],
    notes: [
      "Pancreatic cancer: oxaliplatin (in FOLFIRINOX and NALIRIFOX) and nab-paclitaxel are the causes. Pancreatic Cancer UK says it may be worse in the cold, that gloves, warm socks and avoiding cold food and drinks help, that it normally improves after treatment but can worsen in the first months, and to tell the team early so the dose can be changed before it becomes long term. Macmillan adds that oxaliplatin can rarely cause a throat spasm in the cold in the first days after a dose.",
      "The ASCO guideline (Loprinzi 2020) found no agent prevents chemotherapy neuropathy and that duloxetine is the only drug with evidence for established painful neuropathy.",
    ] },
  { id: "neutropenia", cancers: [CANCER], links: [MAC_FOLFIRINOX, MAC_NAB_PACLITAXEL, CG151],
    notes: ["FOLFIRINOX, NALIRIFOX and gemcitabine with nab-paclitaxel all lower white cells. Macmillan says to ring the 24-hour number straight away for a temperature above 37.5 C or below 36 C, or for feeling unwell even with a normal temperature; blood counts are checked before each dose and treatment is delayed if they are low."] },
  { id: "febrile-neutropenia", cancers: [CANCER], links: [NHS_SEPSIS, MAC_SEPSIS, CG151],
    notes: ["Pancreatic cancer chemotherapy: the NHS says call 999 or go to A&E for breathing very fast, confusion or slurred speech, blue, pale or blotchy skin, a very high or very low temperature, shivering, or a rash that does not fade when pressed. A blocked bile duct or stent is a second route to sepsis in this cancer, so fever counts even when the blood count is normal."] },
  { id: "hand-foot-syndrome", cancers: [CANCER], links: [MAC_FOLFIRINOX, MAC_GEMCAP],
    notes: ["Fluorouracil (in FOLFIRINOX) and capecitabine (in GemCap and chemoradiotherapy) can cause sore, red or peeling palms and soles; Macmillan says to contact the 24-hour line, especially with broken skin or if walking is difficult, and to moisturise, wear gloves for housework and loose cotton socks."] },
  { id: "mucositis", cancers: [CANCER], links: [PCUK_CHEMO_SIDE, MAC_FOLFIRINOX],
    notes: ["Pancreatic Cancer UK says a soft toothbrush, rinsing with cool water after eating and an alcohol-free mouthwash help with a sore mouth on chemotherapy, and to ask the team to check for oral thrush, which is common and easy to treat; Macmillan says ring if soreness stops you eating or drinking or there are ulcers or white patches."] },
  { id: "cancer-related-fatigue", cancers: [CANCER], links: [PCUK_FATIGUE, MAC_SYMPTOMS, FABI_2020],
    notes: ["Pancreatic cancer: Pancreatic Cancer UK says fatigue is extreme tiredness that is not always linked to activity and that the cancer, its symptoms and its treatments all cause it. Macmillan says gentle strengthening exercise and walking reduce fatigue, that anaemia is a treatable cause, and that tiredness can also be a sign of depression worth raising. Poor digestion and untreated diabetes are two pancreatic-specific causes the dietitian can check."] },
  { id: "vte", cancers: [CANCER], links: [PCUK_CLOTS, NHS_DVT, PCUK_CHEMO_SIDE],
    notes: ["Pancreatic cancer carries one of the highest clot risks of any cancer, and chemotherapy and surgery add to it. Pancreatic Cancer UK says tell the team straight away, or go to A&E or call 999, for pain, swelling or warmth in a leg or arm, sudden breathlessness, sudden chest pain or coughing up blood; that the oncologist should consider blood-thinning medicine during chemotherapy; and that clots are treated with tablets or injections for three to six months at first, usually without stopping cancer treatment."] },
  { id: "cancer-associated-thrombosis", cancers: [CANCER], links: [PCUK_CLOTS, NG85],
    notes: ["NICE NG85 points to its venous thromboembolism guideline for people with pancreatic cancer; Pancreatic Cancer UK says injections of blood-thinning medicine continue for about four weeks after surgery and that a nurse shows you how to give them."] },
  { id: "oncology-nutrition", cancers: [CANCER], links: [PCUK_DIET, PCUK_PERT_HOW, CRUK_DIET, PHILLIPS_2021, ROBERTS_2019],
    notes: [
      "Pancreatic cancer is the disease where nutrition support starts with enzymes. Pancreatic Cancer UK's starting doses are at least 50,000 to 75,000 units with a main meal and 25,000 to 50,000 with a snack or milky drink, half with the first mouthfuls and half spread through the meal, swallowed with a cool drink, more for larger or fattier meals, and reviewed regularly; the UK consensus (Phillips 2021) sets the same starting point.",
      "A population-based study (Roberts 2019) found people with pancreatic cancer prescribed enzyme replacement lived longer than those who were not; NICE NG85 says offer enteric-coated pancreatin in unresectable disease and consider it before and after resection.",
    ] },
  { id: "enteral-parenteral-nutrition", cancers: [CANCER], links: [NG85, PCUK_AFTER_SURGERY],
    notes: ["NICE NG85 says for people who have had a pancreatoduodenectomy and have a functioning gut, offer early enteral nutrition (oral or tube feeding) rather than parenteral nutrition; Pancreatic Cancer UK says a tube through the nose or a small hole in the tummy may be used until the stomach works normally, and feeding into a vein is reserved for a pancreatic leak."] },
  { id: "prehabilitation", cancers: [CANCER], links: [PCUK_WHO_SURGERY, MAC_SURGERY, CRUK_PREHAB],
    notes: ["Before a Whipple operation: Pancreatic Cancer UK says some hospitals offer prehabilitation focused on diet and physical activity to help you recover faster; Macmillan says stopping smoking lowers the risk of a chest infection and helps the wound heal, and that some hospitals run an enhanced recovery programme."] },
  { id: "pain-management", cancers: [CANCER], links: [PCUK_PAIN, CRUK_SYMPTOMS_ADVANCED, MAC_SYMPTOMS, NG85, WYSE_2011],
    notes: [
      "Pancreatic cancer pain is often nerve pain from pressure on the coeliac plexus behind the pancreas. Cancer Research UK lists the steps: paracetamol, then weak and strong opioids with regular laxatives, anti-inflammatories, and amitriptyline or gabapentin for burning or shooting pain; cancer treatment and palliative radiotherapy can also shrink what is pressing on the nerves.",
      "NICE NG85 says consider an EUS-guided or image-guided coeliac plexus block for uncontrolled pain, unacceptable opioid side effects or escalating doses; a randomised double-blind trial (Wyse 2011) found early EUS-guided neurolysis reduced pain at three months compared with pain medicines alone.",
    ] },
  { id: "palliative-care", cancers: [CANCER], links: [NHS_PC_TREATMENT, PCUK_INOPERABLE, MARIE_CURIE, TEMEL],
    notes: ["Pancreatic cancer: the NHS says people whose cancer cannot be cured are referred to the palliative care or symptom control team, which works with you to manage symptoms and helps you and your loved ones get support. Pancreatic Cancer UK says these services are not just for the end of life and are available at any point; NICE NG85 asks teams to assess the psychological impact of fatigue, pain, gut symptoms, nutrition, anxiety and depression throughout care."] },
  { id: "germline-testing", cancers: [CANCER], links: [PCUK_FAMILY_HISTORY, PCUK_HEREDITARY, MAC_BRCA, NG85, TA750, POLO_PAPER],
    notes: ["Pancreatic cancer: about one in ten cases runs in families (Pancreatic Cancer UK). A germline BRCA1 or BRCA2 result changes treatment (platinum chemotherapy is favoured; in POLO maintenance olaparib lengthened the time before growth) and matters for relatives, who may be offered testing and, under NICE NG85, MRI/MRCP or EUS surveillance if they carry BRCA1, BRCA2, PALB2 or CDKN2A and have a first-degree relative with the cancer. NICE's appraisal of olaparib in pancreatic cancer (TA750) was terminated without a recommendation, so NHS funding is a question for your team."] },
  { id: "emotional-support-cancer-uk", cancers: [CANCER], links: [NHS_PC_SUPPORT, PCUK_EMOTIONAL, PCUK_FAMILIES, CRUK_COPING, MAGGIES],
    notes: ["For pancreatic cancer the NHS lists Pancreatic Cancer UK (0808 801 0707, with a nurse service, forum and local groups), Macmillan (0808 808 00 00), Cancer Research UK nurses (0808 800 4040), Maggie's (0300 123 1801) and Marie Curie (0800 090 2309). Pancreatic Cancer UK's specialist nurses can be reached by phone, email or WhatsApp, its online community is called Circles, and it says people with this cancer are more likely to have anxiety or depression and that getting support helps."] },
  { id: "financial-toxicity", cancers: [CANCER], links: [PCUK_WORK_MONEY, MAC_WORK],
    notes: ["Pancreatic Cancer UK says you are protected from discrimination at work and your employer must make reasonable adjustments; that PIP, Attendance Allowance or Carer's Allowance may apply; that where the cancer cannot be cured an SR1 form from your doctor or nurse speeds up claims; that prescriptions are free in England with a medical exemption certificate (form FP92A) for anyone having cancer treatment; and that Macmillan's benefits advisers and calculator can work out what you can claim."] },
];

