const draft = (x: Omit<TermInput, "kind" | "asOf">): TermInput => ({ kind: "term", asOf, cancers: [CANCER], ...x });
export const pancreaticLivingTermDrafts: TermInput[] = [
  draft({ id: "pert-pancreatic-cancer", name: "Pancreatic enzyme replacement therapy (PERT): how to take it", category: "Treatment jargon", aka: ["PERT", "Creon", "Nutrizym", "Pancrex", "pancreatin", "enzyme capsules", "pancreatic exocrine insufficiency"],
    tldr: "Most people with pancreatic cancer need enzyme capsules with every meal, snack and milky drink because the cancer or the operation stops the pancreas digesting food; start with about 50,000 to 75,000 units for a main meal and 25,000 to 50,000 for a snack, half at the start and half through the meal, and take more for bigger or fattier meals.",
    summary: `Pancreatic Cancer UK says PERT replaces the enzymes the pancreas would normally make, that most people with pancreatic cancer will need it, for life, and that it can make a big difference to how you feel and to coping with chemotherapy. Its dosing rules: take it with all meals and snacks and with drinks that are more than half milk; swallow the capsules whole with a couple of sips of a cool drink (hot drinks stop them working); take half with the first few mouthfuls and spread the rest through the meal; there is no set daily dose, so start with at least 50,000 or 75,000 units for a main meal and 25,000 or 50,000 for a snack and increase as needed (a healthy pancreas makes about 720,000 units for a small meal); take more for larger or fattier food, and with nutritional supplement drinks; do not cut fat out of your diet to manage symptoms. Capsules can be opened and the granules mixed with a teaspoon of cold acidic food such as apple sauce, never chewed or mixed with hot food. In hospital, ask to keep your PERT with you so it is taken with food, not at drug rounds.\n\nIf symptoms persist: check the dose and timing, ask about a proton pump inhibitor (stomach acid stops the enzymes working), a different brand, or another cause such as bile acid diarrhoea, small intestinal bacterial overgrowth or medicines. Extra enzymes pass harmlessly through. The UK consensus guideline (Phillips 2021) sets the same starting doses, and a population-based study (Roberts 2019) found people prescribed enzymes lived longer. NICE NG85 says offer enteric-coated pancreatin for unresectable disease and consider it before and after resection; it notes the 2024 supply disruption and points prescribers to the Specialist Pharmacy Service tool for equivalent products. All PERT is pork-derived; Pancreatic Cancer UK says organisations representing Jewish and Muslim communities and the Vegetarian and Vegan Societies have said its use is acceptable. ${NOT_ADVICE}`,
    links: [PCUK_PERT, PCUK_PERT_HOW, PCUK_PERT_NOT_HELPING, CRUK_DIET, PHILLIPS_2021, ROBERTS_2019, NG85], terms: ["cachexia", "nutrition-impact-symptoms", "whipple"], technologies: ["oncology-nutrition"] }),
  draft({ id: "type-3c-diabetes-pancreatic-cancer", wikipedia: "https://en.wikipedia.org/wiki/Type_3c_diabetes", name: "Type 3c diabetes with pancreatic cancer", category: "Side effects", aka: ["type 3c diabetes", "pancreatogenic diabetes", "diabetes after Whipple", "new-onset diabetes"],
    tldr: "Pancreatic cancer or surgery to remove part or all of the pancreas can stop it making enough insulin and glucagon; the result is type 3c diabetes, which behaves differently from type 1 and type 2, usually needs tablets or insulin, and is best managed by a diabetes nurse and a specialist dietitian who know you have pancreatic cancer.",
    summary: `Pancreatic Cancer UK says the pancreas normally makes insulin and glucagon to keep blood sugar steady, that the cancer or its removal can stop it making enough of either, and that this is type 3c diabetes: blood sugar may run too high or too low, a lot of type 1 and type 2 information may not be right for you, and most people need medicine. Symptoms are thirst, weight loss, passing urine more often, fatigue, light-headedness, palpitations, sweating and confusion. It asks you to make sure you know who to contact about your diabetes, to tell the diabetes nurse and dietitian that you have type 3c diabetes and pancreatic cancer, and to ask for a specialist dietitian referral if you have not had one. After a Whipple operation, blood sugar is checked in hospital and you are asked to see your GP for thirst or passing urine more often at home; a systematic review (Scholten 2018) found new diabetes after pancreatoduodenectomy in about 16 in 100 people. If the whole pancreas is removed, insulin is needed for life (Macmillan).\n\nCancer Research UK says treatment may be insulin injections or tablets such as metformin, that you are referred to a specialist diabetic nurse and taught to test blood sugar by finger prick or a skin sensor, what to eat, how to inject and what to do if sugar drops too low; some nutritional supplement drinks affect blood sugar, so check with the dietitian. Pancreatic Cancer UK says if you take insulin you must tell the DVLA (DVA in Northern Ireland) and not drive until they say you can. Recently diagnosed diabetes can also be a symptom of pancreatic cancer before diagnosis. ${NOT_ADVICE}`,
    links: [PCUK_DIABETES, CRUK_DIET, PCUK_SURGERY_SIDE, MAC_SURGERY, SCHOLTEN_2018], terms: ["whipple", "pert-pancreatic-cancer"] }),
  draft({ id: "coeliac-plexus-block", name: "Coeliac plexus block for pancreatic cancer pain", category: "Procedures", aka: ["celiac plexus block", "coeliac plexus neurolysis", "EUS-guided coeliac plexus neurolysis", "nerve block"],
    tldr: "An injection that deadens the bundle of nerves behind the pancreas, done through the back under X-ray or ultrasound guidance or from inside the stomach during an endoscopic ultrasound; NICE suggests considering it when pancreatic pain is not controlled, opioid side effects are unacceptable or doses keep rising.",
    summary: `Pancreatic Cancer UK says the cancer can press on a bundle of nerves called the coeliac plexus near the pancreas, causing pain in the tummy or back, and that painkillers or a nerve block may help. NICE NG85 (1.5.1) says consider EUS-guided or image-guided percutaneous neurolytic coeliac plexus block for people with uncontrolled pancreatic pain, unacceptable opioid adverse effects or escalating doses of analgesics, and (1.5.2) do not offer thoracic splanchnicectomy. Macmillan describes the procedure: you may be sedated, you lie on your front and the doctor injects local anaesthetic and a steroid (or a nerve-destroying agent) into the nerves through your back under X-ray or ultrasound guidance, or the injection is given from inside the body during an endoscopic ultrasound; the back may be sore for a few hours or days. In a randomised double-blind trial (Wyse 2011) of 96 people with inoperable pancreatic cancer, early EUS-guided coeliac plexus neurolysis at the time of the diagnostic endoscopy reduced pain at three months compared with pain medicines alone, with a trend to lower opioid use. Cancer Research UK says the block stops the signals that cause pain in the upper abdomen and is one option among painkillers, nerve-pain drugs (amitriptyline, gabapentin), palliative radiotherapy and cancer treatment itself. ${NOT_ADVICE}`,
    links: [NG85, PCUK_PAIN, MAC_SYMPTOMS, CRUK_SYMPTOMS_ADVANCED, WYSE_2011], technologies: ["pain-management", "palliative-care", "endoscopic-ultrasound-systems"] }),
  draft({ id: "eating-after-whipple", name: "Eating after a Whipple operation: slow stomach emptying, dumping and bowel changes", category: "Side effects", aka: ["delayed gastric emptying", "gastroparesis after surgery", "dumping syndrome", "steatorrhoea after surgery", "post-Whipple diet"],
    tldr: "After a Whipple operation the stomach can be slow to empty for days or weeks, meals feel full quickly, and pale, oily stools mean enzymes are needed; small frequent meals, enzyme capsules with everything, a dietitian's review and patience over several months are the pattern most people describe.",
    summary: `Pancreatic Cancer UK says it takes time to eat normally again after surgery, you may lose your appetite or feel full quickly, eating little and often helps, and the stomach may not empty normally for the first days, when some people are fed through a tube until it does; the International Study Group of Pancreatic Surgery defines this delayed gastric emptying by how long a nasogastric tube or a liquid-only diet is needed (Wente 2007). Feeling sick after surgery is usually temporary and is treated with medicines and smaller meals. Removing part of the pancreas can cause weight loss, diarrhoea, tummy discomfort or bloating from poor digestion; pale, oily, smelly stools that float are the sign, and enzyme capsules with every meal and snack are the treatment (the dietitian should check whether you need PERT before and after surgery). Bowels do not work normally for a few days, and opioid painkillers cause constipation, so laxatives are given alongside them.\n\nMacmillan says a modified (pylorus-preserving) Whipple's keeps the stomach valve while a classic Whipple's removes the lower stomach, which is why some people feel very full or get sweaty, faint or have diarrhoea soon after sugary meals (dumping); the dietitian's usual advice is small meals, protein first, drinks between rather than with meals. Pancreatic Cancer UK says there are no foods to totally avoid, that smaller portions with more calories and protein help you regain weight, and that recovery of appetite and the range of food you can digest returns gradually; one person quoted found they could manage a spoon of cereal rather than a bowl at first. If diarrhoea persists on enzymes, bile acid diarrhoea or small intestinal bacterial overgrowth are looked for. ${NOT_ADVICE}`,
    links: [PCUK_AFTER_SURGERY, PCUK_SURGERY_SIDE, PCUK_BOWEL, MAC_SURGERY_TYPES, MAC_SURGERY, WENTE_2007], terms: ["whipple", "pert-pancreatic-cancer", "nutrition-impact-symptoms"], technologies: ["oncology-nutrition"] }),
  draft({ id: "chemotherapy-side-effects-pancreatic", name: "Living with FOLFIRINOX, NALIRIFOX and gemcitabine with nab-paclitaxel", category: "Side effects", aka: ["FOLFIRINOX side effects", "irinotecan diarrhoea", "oxaliplatin cold sensitivity", "nab-paclitaxel side effects", "DPD test"],
    tldr: "The three main regimens share low blood counts, tiredness, sickness and sore mouth; FOLFIRINOX and NALIRIFOX add irinotecan diarrhoea and oxaliplatin's cold-triggered tingling and rare throat spasm, gemcitabine with nab-paclitaxel adds hair loss and neuropathy, and every regimen comes with the same temperature rule for ringing the 24-hour line.",
    summary: `Macmillan's FOLFIRINOX page: each cycle is 2 weeks, with oxaliplatin, folinic acid and irinotecan as drips on day 1 and fluorouracil by injection then through a small pump for about 46 hours, often via a PICC line; a DPD blood test comes first because low DPD raises the risk of severe fluorouracil side effects. Irinotecan can cause sweating, cramps, watery eyes and diarrhoea within 24 hours (acute cholinergic syndrome, prevented with atropine); oxaliplatin can rarely cause a throat spasm in the cold in the first days, so avoid iced drinks and cover your mouth in cold weather. Ring the 24-hour number straight away for a temperature above 37.5 C or below 36 C, feeling unwell even with a normal temperature, diarrhoea 4 or more times a day or at night, cramps, or anti-diarrhoea medicine not working within 24 hours, unexplained bruising or bleeding, sore red or peeling palms and soles, or a sore mouth that stops you eating; call 999 for chest pain or difficulty breathing (fluorouracil affects the heart in under 1 in 100).\n\nMacmillan's nab-paclitaxel page: given weekly for 3 weeks then a week off with gemcitabine; nearly everyone loses the hair on their head (scalp cooling may be offered); ring for 3 or more loose stools a day; tingling or numb hands and feet should be reported so the dose can be changed. Pancreatic Cancer UK says neuropathy is most common with FOLFIRINOX, FOLFOX and nab-paclitaxel, is worse in the cold, normally improves after treatment but can worsen in the first months, and that a diary of side effects helps at each visit. Its blood clot rule: pain, swelling or redness in a limb, sudden chest pain or breathlessness means calling the emergency number or going to A&E. NALIRIFOX (liposomal irinotecan, oxaliplatin, fluorouracil) shares the FOLFIRINOX pattern; in NAPOLI 3 diarrhoea and low potassium were more frequent than with gemcitabine and nab-paclitaxel, and neuropathy and low white cells less so. ${NOT_ADVICE}`,
    links: [MAC_FOLFIRINOX, MAC_NAB_PACLITAXEL, PCUK_CHEMO_SIDE, CRUK_CHEMO, NAPOLI3_PAPER, LOPRINZI], drugs: ["folfirinox", "nalirifox", "gemcitabine-nab-paclitaxel"], terms: ["peripheral-neuropathy", "neutropenia", "febrile-neutropenia", "hand-foot-syndrome", "mucositis", "vte"] }),
  draft({ id: "urgent-help-pancreatic-cancer", name: "When to seek urgent help with pancreatic cancer (NHS 111 and 999)", category: "Clinical",
    tldr: "Call 999 for signs of sepsis, vomiting blood with feeling faint, or a swollen painful leg with breathlessness or chest pain. Ring the hospital's 24-hour line at once for a temperature over 37.5 C or below 36 C, shivering with a stent or jaundice, vomiting large amounts, heavy diarrhoea or uncontrolled pain. Ask for an urgent GP appointment or use 111 for returning yellow eyes or skin.",
    summary: `The wording, situation by situation. Sepsis (999 or A&E, NHS): breathing very fast; confused, slurred speech or not making sense; blue, pale or blotchy skin, lips or tongue; a very high or very low temperature, feeling hot or cold to the touch, or shivery; a rash that does not fade when pressed. Infection on chemotherapy (24-hour line, Macmillan): a temperature above 37.5 C or below 36 C, or feeling unwell even with a normal temperature. Blocked or infected bile duct or stent (Pancreatic Cancer UK and the NHS): yellow eyes or skin, dark urine, pale stools or itching returning means an urgent GP appointment or 111; fever or shivering with a stent means the 24-hour line the same day and 999 for sepsis signs; after surgery, sudden worse pain with a high temperature means A&E. Blocked duodenum or bowel (Pancreatic Cancer UK): vomiting large amounts especially after food, feeling full, tummy pain and bloating; contact the team, or A&E if you cannot reach them; the NHS says being sick for more than 2 days is a 111 call and green vomit or a sudden severe tummy ache is 999. Bleeding (NHS): vomiting blood, black stools, feeling faint, dizzy, confused, cold and clammy or breathing fast: call 999 or go to A&E; if the vomiting of blood has stopped and there are no other symptoms, an urgent GP appointment or 111. Blood clot (Pancreatic Cancer UK and the NHS): pain, swelling, warmth or colour change in a leg or arm, sudden or gradual breathlessness, sudden chest pain, coughing up blood or fainting: tell the team straight away, or go to A&E or call 999; DVT symptoms with breathlessness or chest pain are always 999. Diarrhoea on chemotherapy (Macmillan): 4 or more times a day, at night, with cramps or not settling with the medicine within 24 hours on FOLFIRINOX; 3 or more loose stools a day on nab-paclitaxel; the NHS adds that diarrhoea for more than 7 days is a 111 call. Low blood sugar on insulin: follow the plan your diabetes nurse gave you and tell the team. Do not drive yourself to A&E. ${NOT_ADVICE}`,
    links: [NHS_SEPSIS, NHS_PC_SYMPTOMS, NHS_JAUNDICE, NHS_DVT, MAC_SEPSIS, MAC_FOLFIRINOX, PCUK_STENT_BILE, PCUK_STENT_DUODENUM, PCUK_CLOTS, NHS_111, NHS_999], terms: ["febrile-neutropenia", "acute-cholangitis", "biliary-stent-problems", "duodenal-stenting-gastric-outlet", "vte"] }),
  draft({ id: "work-and-money-pancreatic-cancer-uk", name: "Work and money with pancreatic cancer (UK)", category: "Clinic basics", aka: ["sick pay", "reasonable adjustments", "SR1 form", "free prescriptions", "PIP"],
    tldr: "Cancer counts as a disability, so your employer must consider reasonable adjustments; benefits such as PIP, Attendance Allowance and Carer's Allowance may apply, an SR1 form from your doctor speeds claims where the cancer cannot be cured, prescriptions are free in England with an FP92A certificate, and Macmillan's advisers and calculator work out what you can claim.",
    summary: `Pancreatic Cancer UK says you have rights at work and are protected from discrimination, that your employer must make reasonable adjustments such as part-time hours, flexible start and finish times, changed duties, more breaks or working from home, and that a family member who cares for you may also need to stop working. On money it says to get advice as soon as possible from Macmillan, Carers UK, Carers Trust or Citizens Advice; that you and your family may be able to claim Carer's Allowance, Personal Independence Payment, Adult Disability Payment (Scotland) or Attendance Allowance; that Macmillan's online Benefits Calculator and advisers help with forms; that if the cancer cannot be cured, special rules speed up claims and your doctor or nurse fills in an SR1 form (BASRiS in Scotland); that prescriptions are free in Scotland, Wales and Northern Ireland and, in England, free for anyone having treatment for cancer or its effects with a medical exemption certificate (ask for form FP92A); and that help exists with hospital travel, parking, energy bills and grants. After a Whipple operation, going back to work may take at least three months, longer with chemotherapy, and you may return with fewer hours or more breaks. Macmillan says the Equality Act 2010 (England, Scotland and Wales) protects people with cancer from less favourable treatment and that Statutory Sick Pay applies where there is no company scheme. ${NOT_ADVICE}`,
    links: [PCUK_WORK_MONEY, PCUK_GOING_HOME, MAC_WORK, NHS_CARER_ASSESSMENT, NHS_CARER_BENEFITS], terms: ["financial-toxicity"] }),
  draft({ id: "carers-pancreatic-cancer-uk", name: "Carers: what you can do and UK carer support (pancreatic cancer)", category: "Clinic basics", aka: ["caregiver", "caring for someone with pancreatic cancer", "family and friends"],
    tldr: "A carer is anyone giving unpaid help to someone with cancer who could not manage without it; you can come to appointments, keep the enzyme dose and the medicine list, learn the sepsis, stent, clot and blocked-bowel signs, tell the team you are the carer, ask the council for a free carer's assessment, and use Pancreatic Cancer UK's nurses, carer booklet and Circles community for yourself.",
    summary: `Pancreatic Cancer UK says it can be a huge shock when someone close to you is diagnosed, that looking after yourself may help you both, that one of the best ways to help is learning about symptoms, how to manage them and who to ask for help, and that its specialist nurses take calls, emails and WhatsApp messages from family members; it has a booklet for carers, information on supporting children and on communicating when talking about cancer is hard, and tailored emails for families. Practical roles it and Macmillan describe: going to appointments and writing down answers, keeping the 24-hour number and the list of medicines and enzyme doses, watching for the emergencies on the red cards (fever or shivering with a stent, returning jaundice, vomiting large amounts, a swollen leg or sudden breathlessness, vomiting blood, sepsis signs), helping with small frequent meals and enzymes with everything, and telling the team you are the carer so you are part of the plans for going home. Macmillan says you are a carer if you give any unpaid help to someone who could not manage without it, that driving to appointments counts, and that its support line is open to carers. The NHS says anyone over 18 who cares for someone can ask their council for a free carer's assessment, and lists Carer's Allowance among the benefits for carers; Pancreatic Cancer UK says a family member who stops work to care may be able to claim it. ${NOT_ADVICE}`,
    links: [PCUK_FAMILIES, MAC_CARERS, NHS_CARER_ASSESSMENT, NHS_CARER_BENEFITS, PCUK_END_OF_LIFE], terms: ["emotional-support-cancer-uk", "urgent-help-pancreatic-cancer"] }),
];

